paths={n:prefix+n for n in ['trades.csv','config.snapshot.json','metrics.json']};paths.update({'BTCUSDT.15m.jsonl':'data/candles/BTCUSDT.15m.jsonl','costs.ts':'src/backtest/costs.ts','INTEGRITY.md':'data/INTEGRITY.md'})
