def calc(rr):
 net=sum((D(r['realized_pnl']) for r in rr),D(0));cost={k:sum((D(r[k]) for r in rr),D(0)) for k in ['fees','slippage','funding']};win=sum((max(D(0),D(r['realized_pnl'])) for r in rr),D(0));loss=-sum((min(D(0),D(r['realized_pnl'])) for r in rr),D(0));checks=0
 for r in rr:
  sign=1 if r['direction']=='LONG' else -1;cash=sign*(D(r['exit_price'])-D(r['entry_price']))*D(r['quantity'])-D(r['fees'])-D(r['funding']);assert abs(cash-D(r['realized_pnl']))<D('.001');checks+=1
 return {'n':len(rr),'net_USDT_model':str(net),'costs':{k:str(v) for k,v in cost.items()},'PF':str(win/loss) if loss else None,'conditional_extra_same_path_cost_net':str(net-sum(cost.values(),D(0))),'exit_reasons':dict(collections.Counter(r['exit_reason'] for r in rr)),'cash_checks':checks}
