out={'source_pin':pin,'config_hash':json.loads((p/'config.snapshot.json').read_text())['hash'],'hashes':{n:hashlib.sha256((p/n).read_bytes()).hexdigest() for n in paths},'all':calc(a),'BTC':calc(b),'BTC_by_source_sample':{s:calc([r for r in b if r['sample']==s]) for s in sorted({r['sample'] for r in b})},'BTC_candles':len(c),'candle_start':times[0],'candle_end':times[-1],'duplicate_timestamps':len(times)-len(set(times)),'gaps':gaps,'promotion':False,'full_engine_rerun':False,'full_cost_double_rerun':None,'TP1_first':None,'actual_emergency_5min':None,'native_LBank':False,'limits':['Bitget SPOT proxy with model short/funding, not actual LBank futures.','Slippage already embedded in fill prices, not subtracted twice for base net.','Extra same-path fees+slip+funding is arithmetic sensitivity only; doubled-cost rerun may change prices/size/decisions.','All default BTC records retained including source eod exits; eod not profitability proof.','15m data cannot prove first5min risk/TP1 order.','Portfolio-dependent original BTC allocation, not standalone BTC rerun; source IS/OOS already viewed not new independent sample.','Rules are unofficial approximation; VMC exact formula not published.']};(p/'report.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
